import * as React from "react"
import { Link } from "gatsby"
import { useLanguage } from "./language"
import { localizePost } from "./localize-post"

const PostList = ({ posts }) => {
  const { locale } = useLanguage()
  return (
    <div className="scroll-box">
      <ol className="post-list">
        {posts
          .map(post => localizePost(post, locale))
          .map(post => (
            <li key={post.fields.slug}>
              <Link to={post.fields.slug} className="post-link-wrapper">
                <article className="post-list-item">
                  <time
                    className="post-date"
                    dateTime={post.frontmatter.rawDate}
                  >
                    {post.frontmatter.date}
                  </time>
                  <div className="post-copy">
                    <h2>{post.frontmatter.title || post.fields.slug}</h2>
                    <p
                      dangerouslySetInnerHTML={{
                        __html: post.frontmatter.description || post.excerpt,
                      }}
                    />
                  </div>
                </article>
              </Link>
            </li>
          ))}
      </ol>
    </div>
  )
}

export default PostList
