import * as React from "react"
import { Link, graphql } from "gatsby"
import { StaticImage } from "gatsby-plugin-image"
import Layout from "../components/layout"
import Seo from "../components/seo"
import PostList from "../components/post-list"
import { useLanguage } from "../components/language"

const Page = ({ data, location }) => {
  const { t } = useLanguage()
  const posts = data.newsPosts.nodes
  return (
    <Layout location={location}>
      <section className="home-intro" aria-labelledby="intro-title">
        <div className="intro-identity">
          <StaticImage
            className="intro-portrait"
            layout="constrained"
            formats={["auto", "webp", "avif"]}
            src="../images/profile-pic-high.png"
            width={200}
            height={200}
            quality={100}
            alt={t(
              "七原宇紀のプロフィール写真",
              "Portrait of Takanori Nanahara"
            )}
          />
          <h1 id="intro-title" className="intro-name">
            <span>
              Takanori Nanahara<span className="name-period">.</span>
            </span>
            <small className="intro-name-ja" lang="ja">
              七原 宇紀
            </small>
          </h1>
        </div>
        <div className="intro-bottom">
          <p>
            {t("空間と、人のふるまい。", "Space and human behavior.")}
            <br />
            {t(
              "建築・空間認知・経路探索を研究しています。",
              "Exploring architecture, spatial cognition, and navigation."
            )}
          </p>
          <Link className="text-link" to="/about">
            {t("プロフィールを見る", "About me")}
          </Link>
        </div>
        <div className="research-topics">
          <span>Architecture</span>
          <span>Spatial Cognition</span>
          <span>Navigation</span>
        </div>
      </section>
      <section className="listing-section" aria-labelledby="news-heading">
        <div className="section-heading">
          <h2 id="news-heading" className="h1-scrollboxtitle">
            News<span className="heading-dot">.</span>
          </h2>
          <p>
            {t("お知らせ", "Updates")}{" "}
            <span className="post-count">
              {posts.length.toString().padStart(2, "0")}
            </span>
          </p>
        </div>
        <PostList posts={posts} />
      </section>
    </Layout>
  )
}
export default Page
export const Head = () => <Seo title="Home" />

export const pageQuery = graphql`
  {
    site {
      siteMetadata {
        title
      }
    }
    newsPosts: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/content/news/" }
        fields: { locale: { eq: "ja" } }
      }
      sort: { frontmatter: { date: DESC } }
    ) {
      nodes {
        english {
          excerpt
          frontmatter {
            title
            description
          }
        }
        excerpt
        fields {
          slug
        }
        frontmatter {
          date(formatString: "YYYY.MM.DD")
          rawDate: date
          title
          description
        }
      }
    }
  }
`
